import { Pipe, PipeTransform } from '@angular/core';

export type MembershipRole = 'OWNER' | 'MANAGER' | 'MEMBER';

@Pipe({
  name: 'membershipRole',
  standalone: true,
})
export class MembershipRolePipe implements PipeTransform {
  transform(role: MembershipRole): string {
    const roleMap: Record<MembershipRole, string> = {
      OWNER: 'Dono',
      MANAGER: 'Gerente',
      MEMBER: 'Membro',
    };

    return roleMap[role] ?? role;
  }
}

import { Pipe, PipeTransform } from '@angular/core';

export type MembershipStatus = 'PENDING' | 'ACTIVE' | 'DECLINED' | 'REVOKED';

@Pipe({
  name: 'membershipStatus',
  standalone: true,
})
export class MembershipStatusPipe implements PipeTransform {
  transform(status: MembershipStatus): string {
    const statusMap: Record<MembershipStatus, string> = {
      ACTIVE: 'Ativo',
      PENDING: 'Pendente',
      DECLINED: 'Recusado',
      REVOKED: 'Revogado',
    };

    return statusMap[status] ?? status;
  }
}

